diff --git a/src/tools/telegram-notify.ts b/src/tools/telegram-notify.ts
--- a/src/tools/telegram-notify.ts
+++ b/src/tools/telegram-notify.ts
@@ -30,9 +30,12 @@ export async function notifyFounder(text: string, deps: NotifyDeps): Promise<Notify
   const url = `https://api.telegram.org/bot${deps.botToken}/sendMessage`;
   const res = await deps.fetch(url, {
     method: "POST",
     headers: { "content-type": "application/json" },
     body: JSON.stringify({ chat_id: deps.chatId, text }),
   });
-  if (!res.ok) return { sent: false, reason: `telegram ${res.status}` };
+  if (!res.ok) {
+    deps.logger.error({ url, status: res.status, body: await res.text() }, "telegram send failed");
+    return { sent: false, reason: `telegram ${res.status}` };
+  }
   return { sent: true };
 }
